import { Component, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { NavbarComponent } from './components/navbar/navbar.component';
import { FooterComponent } from './components/footer/footer.component';

// Enterprise ERP Internal Modules
import { RoleManagementComponent } from './components/role-management/role-management.component';
import { ProductManagementComponent } from './components/product-management/product-management.component';
import { SupplierManagementComponent } from './components/supplier-management/supplier-management.component';
import { ImportManagementComponent } from './components/import-management/import-management.component';
import { CustomsDocsComponent } from './components/customs-docs/customs-docs.component';
import { WarehouseInventoryComponent } from './components/warehouse-inventory/warehouse-inventory.component';
import { ExportManagementComponent } from './components/export-management/export-management.component';
import { AccountsCostingComponent } from './components/accounts-costing/accounts-costing.component';
import { ErpDashboardComponent } from './components/erp-dashboard/erp-dashboard.component';
import { ShipmentTrackerComponent } from './components/shipment-tracker/shipment-tracker.component';
import { RfqCalculatorComponent } from './components/rfq-calculator/rfq-calculator.component';

export type ErpModuleTab = 
  | 'dashboard'
  | 'roles' 
  | 'products' 
  | 'suppliers' 
  | 'imports' 
  | 'shipments' 
  | 'customs' 
  | 'warehouse' 
  | 'exports' 
  | 'accounts'
  | 'calculator';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [
    CommonModule,
    NavbarComponent,
    FooterComponent,
    RoleManagementComponent,
    ProductManagementComponent,
    SupplierManagementComponent,
    ImportManagementComponent,
    CustomsDocsComponent,
    WarehouseInventoryComponent,
    ExportManagementComponent,
    AccountsCostingComponent,
    ErpDashboardComponent,
    ShipmentTrackerComponent,
    RfqCalculatorComponent
  ],
  template: `
    <div class="min-h-screen bg-slate-950 text-slate-100 flex flex-col selection:bg-emerald-500 selection:text-slate-950">

      <!-- Internal System Header & Role Status -->
      <app-navbar></app-navbar>

      <!-- Department Workspace Navigation Tabs -->
      <nav class="bg-slate-900/90 border-b border-slate-800 backdrop-blur-md sticky top-[65px] z-40 px-4 py-2.5 overflow-x-auto shadow-xl">
        <div class="max-w-7xl mx-auto flex items-center gap-1.5 text-xs">

          <button 
            (click)="activeTab.set('dashboard')"
            [class]="activeTab() === 'dashboard' ? 'px-3.5 py-2 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-600 text-slate-950 font-extrabold shadow-lg shadow-emerald-500/20 transition' : 'px-3.5 py-2 rounded-xl text-slate-300 hover:text-white hover:bg-slate-800 font-semibold transition'">
            📊 Executive Dashboard
          </button>

          <button 
            (click)="activeTab.set('roles')"
            [class]="activeTab() === 'roles' ? 'px-3.5 py-2 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-600 text-slate-950 font-extrabold shadow-lg shadow-emerald-500/20 transition' : 'px-3.5 py-2 rounded-xl text-slate-300 hover:text-white hover:bg-slate-800 font-semibold transition'">
            👥 Roles & Security
          </button>

          <button 
            (click)="activeTab.set('products')"
            [class]="activeTab() === 'products' ? 'px-3.5 py-2 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-600 text-slate-950 font-extrabold shadow-lg shadow-emerald-500/20 transition' : 'px-3.5 py-2 rounded-xl text-slate-300 hover:text-white hover:bg-slate-800 font-semibold transition'">
            📦 Product Master SKU
          </button>

          <button 
            (click)="activeTab.set('suppliers')"
            [class]="activeTab() === 'suppliers' ? 'px-3.5 py-2 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-600 text-slate-950 font-extrabold shadow-lg shadow-emerald-500/20 transition' : 'px-3.5 py-2 rounded-xl text-slate-300 hover:text-white hover:bg-slate-800 font-semibold transition'">
            🏢 Supplier & Buyer CRM
          </button>

          <button 
            (click)="activeTab.set('imports')"
            [class]="activeTab() === 'imports' ? 'px-3.5 py-2 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-600 text-slate-950 font-extrabold shadow-lg shadow-emerald-500/20 transition' : 'px-3.5 py-2 rounded-xl text-slate-300 hover:text-white hover:bg-slate-800 font-semibold transition'">
            📥 Import PO & LC Desk
          </button>

          <button 
            (click)="activeTab.set('shipments')"
            [class]="activeTab() === 'shipments' ? 'px-3.5 py-2 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-600 text-slate-950 font-extrabold shadow-lg shadow-emerald-500/20 transition' : 'px-3.5 py-2 rounded-xl text-slate-300 hover:text-white hover:bg-slate-800 font-semibold transition'">
            🚢 Vessel Shipments
          </button>

          <button 
            (click)="activeTab.set('customs')"
            [class]="activeTab() === 'customs' ? 'px-3.5 py-2 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-600 text-slate-950 font-extrabold shadow-lg shadow-emerald-500/20 transition' : 'px-3.5 py-2 rounded-xl text-slate-300 hover:text-white hover:bg-slate-800 font-semibold transition'">
            📑 Customs & Duty Vault
          </button>

          <button 
            (click)="activeTab.set('warehouse')"
            [class]="activeTab() === 'warehouse' ? 'px-3.5 py-2 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-600 text-slate-950 font-extrabold shadow-lg shadow-emerald-500/20 transition' : 'px-3.5 py-2 rounded-xl text-slate-300 hover:text-white hover:bg-slate-800 font-semibold transition'">
            🏬 Warehouse Bins
          </button>

          <button 
            (click)="activeTab.set('exports')"
            [class]="activeTab() === 'exports' ? 'px-3.5 py-2 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-600 text-slate-950 font-extrabold shadow-lg shadow-emerald-500/20 transition' : 'px-3.5 py-2 rounded-xl text-slate-300 hover:text-white hover:bg-slate-800 font-semibold transition'">
            📤 Export Sales Orders
          </button>

          <button 
            (click)="activeTab.set('accounts')"
            [class]="activeTab() === 'accounts' ? 'px-3.5 py-2 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-600 text-slate-950 font-extrabold shadow-lg shadow-emerald-500/20 transition' : 'px-3.5 py-2 rounded-xl text-slate-300 hover:text-white hover:bg-slate-800 font-semibold transition'">
            💰 Landed Costing
          </button>

          <button 
            (click)="activeTab.set('calculator')"
            [class]="activeTab() === 'calculator' ? 'px-3.5 py-2 rounded-xl bg-gradient-to-r from-emerald-500 to-teal-600 text-slate-950 font-extrabold shadow-lg shadow-emerald-500/20 transition' : 'px-3.5 py-2 rounded-xl text-slate-300 hover:text-white hover:bg-slate-800 font-semibold transition'">
            🧮 Container Load Calc
          </button>

        </div>
      </nav>

      <!-- Internal Workspace Content Area -->
      <main class="flex-grow max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-8">

        @if (activeTab() === 'dashboard') {
          <app-erp-dashboard></app-erp-dashboard>
        }
        @if (activeTab() === 'roles') {
          <app-role-management></app-role-management>
        }
        @if (activeTab() === 'products') {
          <app-product-management></app-product-management>
        }
        @if (activeTab() === 'suppliers') {
          <app-supplier-management></app-supplier-management>
        }
        @if (activeTab() === 'imports') {
          <app-import-management></app-import-management>
        }
        @if (activeTab() === 'shipments') {
          <app-shipment-tracker></app-shipment-tracker>
        }
        @if (activeTab() === 'customs') {
          <app-customs-docs></app-customs-docs>
        }
        @if (activeTab() === 'warehouse') {
          <app-warehouse-inventory></app-warehouse-inventory>
        }
        @if (activeTab() === 'exports') {
          <app-export-management></app-export-management>
        }
        @if (activeTab() === 'accounts') {
          <app-accounts-costing></app-accounts-costing>
        }
        @if (activeTab() === 'calculator') {
          <app-rfq-calculator></app-rfq-calculator>
        }

      </main>

      <app-footer></app-footer>
    </div>
  `
})
export class AppComponent {
  activeTab = signal<ErpModuleTab>('dashboard');
}
